#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite); library(ggplot2)})
`%||%` <- function(a,b) if (is.null(a)) b else a
op <- parse_args(OptionParser(option_list=list(make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'))))
out <- op$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(m,d='',s='Check input columns and params.json.'){write(toJSON(list(error=m,detail=d,suggestion=s),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json'));quit(status=1)}
tryCatch({
 if(is.null(op$input)||!file.exists(op$input))fail('Input file not found',as.character(op$input)); p<-if(!is.null(op$params)&&file.exists(op$params))fromJSON(op$params,simplifyVector=FALSE)else list()
 val<-function(n,d=NULL,a=character()){x<-p[[n]];if(is.null(x))for(k in a)if(!is.null(p[[k]])){x<-p[[k]];break};if(is.null(x))d else x}; vec<-function(x)if(is.null(x))character()else trimws(as.character(unlist(x))); num<-function(n,d,a=character()){x<-suppressWarnings(as.numeric(unlist(val(n,d,a))[1]));if(is.na(x))d else x}; boo<-function(n,d=FALSE,a=character()){x<-val(n,d,a);if(is.logical(x))isTRUE(x[1])else tolower(as.character(x[1]))%in%c('true','1','yes','y','on')}
 readtab<-function(f){if(tolower(tools::file_ext(f))%in%c('tsv','txt'))read.delim(f,check.names=FALSE,stringsAsFactors=FALSE)else read.csv(f,check.names=FALSE,stringsAsFactors=FALSE)};d<-readtab(op$input);cn<-names(d)
 findcol<-function(x,defs=character(),req=TRUE){z<-c(x,defs);z<-z[!is.null(z)&nzchar(z)];i<-match(tolower(z),tolower(cn));i<-i[!is.na(i)];if(length(i))cn[i[1]]else if(req)fail('Required column not found',paste(z,collapse=', '))else NULL}
 cc<-findcol(val('category_column',NULL,c('category_col','y_column')),c('category','school','term','label','name','id')); mode<-tolower(as.character(val('input_mode','auto')));gc<-findcol(val('group_column',NULL,c('group_col')),c('group','sex','gender'),FALSE);vc<-findcol(val('value_column',NULL,c('value_col','x_column')),c('value','salary','estimate'),FALSE);g1<-as.character(val('group1','Women'));g2<-as.character(val('group2','Men'))
 if(mode=='long'||(!is.null(gc)&&!is.null(vc)&&!all(c('group1_value','group2_value')%in%cn))){if(is.null(gc)||is.null(vc))fail('Long input requires group_column and value_column');z<-data.frame(category=as.character(d[[cc]]),group=as.character(d[[gc]]),value=suppressWarnings(as.numeric(d[[vc]])),stringsAsFactors=FALSE);z<-z[z$group%in%c(g1,g2),,drop=FALSE]}else{c1<-findcol(val('group1_value',NULL,c('group1_column',paste0(g1,'_value'))),c('women','group1_value'));c2<-findcol(val('group2_value',NULL,c('group2_column',paste0(g2,'_value'))),c('men','group2_value'));z<-rbind(data.frame(category=as.character(d[[cc]]),group=g1,value=suppressWarnings(as.numeric(d[[c1]]))),data.frame(category=as.character(d[[cc]]),group=g2,value=suppressWarnings(as.numeric(d[[c2]]))));}
 labc<-findcol(val('label_column',NULL,c('label_col')),character(),FALSE);z$label<-if(is.null(labc))z$category else as.character(d[[labc]])[match(z$category,as.character(d[[cc]]))];z<-z[!is.na(z$value)&nzchar(z$category),,drop=FALSE];if(!nrow(z))fail('No valid numeric rows remain')
 inc<-vec(val('rows_include'));exc<-vec(val('rows_exclude'));if(length(inc))z<-z[seq_len(nrow(z))%in%suppressWarnings(as.integer(inc))|z$category%in%inc,,drop=FALSE];if(length(exc))z<-z[!(seq_len(nrow(z))%in%suppressWarnings(as.integer(exc))|z$category%in%exc),,drop=FALSE];inc<-vec(val('categories_include'));exc<-vec(val('categories_exclude'));if(length(inc))z<-z[z$category%in%inc,,drop=FALSE];if(length(exc))z<-z[!z$category%in%exc,,drop=FALSE];if(!nrow(z))fail('No rows remain after filtering')
 cats<-unique(z$category);ov<-vec(val('category_order'));if(length(ov))cats<-unique(c(ov,cats))else{so<-tolower(as.character(val('sort','none')));sb<-tolower(as.character(val('sort_by','category')));sc<-tapply(z$value,z$category,mean);if(so%in%c('ascending','descending'))cats<-names(sort(sc,decreasing=so=='descending'))else if(sb=='value')cats<-names(sort(sc,decreasing=TRUE))};cats<-cats[cats%in%unique(z$category)];if(boo('reverse_categories'))cats<-rev(cats);top<-as.integer(num('top_n',0));if(top>0)cats<-cats[seq_len(min(top,length(cats)))];z<-z[z$category%in%cats,,drop=FALSE];z$category<-factor(z$category,levels=cats);z$group<-factor(z$group,levels=unique(c(g1,g2,z$group)));z$y<-as.numeric(z$category)+(as.numeric(z$group)-1.5)*num('dodge_width',0)
 seg<-do.call(rbind,lapply(split(z,z$category),function(q){if(nrow(q)>=2)data.frame(x=min(q$value),xend=max(q$value),y=mean(q$y),yend=mean(q$y))else NULL}));pal<-setNames(c(as.character(val('positive_color','#D55E00')),as.character(val('negative_color','#0072B2'))),c(g1,g2));gm<-val('group_colors');if(!is.null(gm)){u<-unlist(gm);if(!is.null(names(u)))pal[names(u)]<-u};z$tooltip<-paste0('School: ',z$category,'<br>',z$group,': ',round(z$value,2))
 q<-ggplot(z,aes(value,y,colour=group,text=tooltip));if(boo('stem_show',TRUE))q<-q+geom_segment(data=seg,aes(x=x,xend=xend,y=y,yend=y),inherit.aes=FALSE,colour=val('stem_color','#9E9E9E'),linewidth=num('stem_width',1),linetype=val('stem_linetype','solid'),alpha=num('stem_alpha',.85));q<-q+geom_point(shape=as.numeric(num('point_shape',16)),size=num('point_size',4),alpha=num('point_alpha',.95),stroke=num('point_stroke',.3));if(boo('label_show'))q<-q+geom_text(aes(label=label),size=num('label_size',3),colour=val('label_color','#333333'),vjust=num('label_nudge_y',-.7),show.legend=FALSE);if(boo('zero_line_show',TRUE))q<-q+geom_vline(xintercept=0,colour=val('zero_line_color','#777777'),linewidth=num('zero_line_width',.5),linetype=val('zero_line_linetype','dashed'))
 q<-q+scale_colour_manual(values=pal,drop=FALSE,name=val('legend_title','Group'))+scale_y_continuous(breaks=seq_along(cats),labels=cats,expand=unlist(val('y_expand',c(.04,.04))));xl<-unlist(val('x_limits'));xb<-unlist(val('x_breaks'));q<-q+scale_x_continuous(breaks=if(length(xb))as.numeric(xb)else waiver(),expand=unlist(val('x_expand',c(.05,.05))));if(length(xl)==2)q<-q+coord_cartesian(xlim=as.numeric(xl))
 q<-q+labs(title=if(boo('title_show',TRUE))val('title','Annual Salary: Women vs Men')else NULL,subtitle=val('subtitle'),caption=val('caption'),x=if(boo('x_title_show',TRUE))val('xlab','Annual salary')else NULL,y=if(boo('y_title_show',TRUE))val('ylab','School')else NULL)+theme_minimal(base_size=num('base_size',11),base_family=val('font_family','sans'))+theme(plot.background=element_rect(fill=val('plot_background','white'),colour=NA),panel.background=element_rect(fill=val('panel_background','white'),colour=NA),panel.grid=if(boo('grid_show',TRUE))element_line(colour=val('grid_major_color','#E5E5E5'))else element_blank(),axis.text=element_text(size=num('axis_text_size',10),colour=val('axis_text_color','#333333'),angle=num('axis_text_angle',0)),plot.title=element_text(size=num('title_size',16),colour=val('title_color','#222222'),face=val('title_face','bold'),hjust=num('title_hjust',0)),legend.position=if(boo('legend_show',TRUE))val('legend_position','right')else'none',legend.text=element_text(size=num('legend_text_size',9)),legend.title=element_text(size=num('legend_title_size',10)),plot.margin=grid::unit(rep(num('margin',.5),4),'cm'))
 w<-num('width',9);h<-num('height',6);dpi<-num('dpi',300);if (!exists('omicscanvas_apply_theme')) { .oc_f <- sub('^--file=', '', grep('^--file=', commandArgs(FALSE), value = TRUE)[1]); .oc_rt <- file.path(dirname(normalizePath(.oc_f, mustWork = FALSE)), '..', '..', 'R', 'runtime', 'omicscanvas_theme.R'); if (!file.exists(.oc_rt)) .oc_rt <- file.path('R', 'runtime', 'omicscanvas_theme.R'); sys.source(.oc_rt, envir = globalenv()) }; q <- omicscanvas_apply_theme(q, p, only = c('aspect_ratio', 'axis_line_color', 'axis_line_show', 'axis_line_width', 'grid_linetype', 'grid_minor_color', 'legend_key_size', 'panel_border_color', 'panel_border_show', 'panel_border_width', 'panel_spacing', 'subtitle_color', 'subtitle_face', 'subtitle_size')); ggsave(file.path(out,'result.svg'),q,width=w,height=h,units='in',dpi=dpi);ggsave(file.path(out,'result.pdf'),q,width=w,height=h,units='in');ggsave(file.path(out,'result.png'),q,width=w,height=h,units='in',dpi=dpi);if(boo('interactive',TRUE)&&requireNamespace('plotly',quietly=TRUE)){pl<-plotly::ggplotly(q,tooltip='text');pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),doubleClick='reset',modeBarButtonsToAdd=c('lasso2d','select2d'));htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE)}else writeLines('<html><body>Plotly is unavailable.</body></html>',file.path(out,'result.html'));write.csv(z[,c('category','group','value','label')],file.path(out,'selected_rows.csv'),row.names=FALSE);write(toJSON(list(plugin='interactive_dumbbell_plot',input_mode=mode,groups=levels(z$group),categories=cats,rows=nrow(z),outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','selected_rows.csv')),auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json'));if(file.exists(file.path(out,'error.json')))unlink(file.path(out,'error.json'));logmsg(sprintf('Rendered %d points across %d categories',nrow(z),length(cats)))
},error=function(e)fail('Plot generation failed',conditionMessage(e)))
